std::optional<std::string> PrinterConversation::connection_skill() const
{
    if (!m_connect_tried || saved(m_printer_name).vendor_id != "BBL")
        return std::nullopt;
    return std::string(Agent::Protocol::SkillTrigger::kConnectBambu);
}

