                            {"items", std::move(items)},
                            {"request_id", transcript.request_id},
                            {"sequence", transcript.request_sequence}};
        request.headers.push_back({"X-Scripted-Sequence", std::to_string(transcript.request_sequence)});
        return request;
    }

